"""Print a compact, TypeScript-like view of selected Public API operations (spike tooling)."""

import json
import sys

doc = json.load(open(sys.argv[1], encoding="utf-8"))
wanted = sys.argv[2:]
MAXDEPTH = int(__import__("os").environ.get("OAS_DEPTH", "6"))


def resolve(node):
    while isinstance(node, dict) and "$ref" in node:
        target = doc
        for part in node["$ref"].lstrip("#/").split("/"):
            target = target[part]
        node = target
    return node


def shape(node, depth=0, indent="  "):
    node = resolve(node)
    if not isinstance(node, dict):
        return str(node)
    if depth > MAXDEPTH:
        return "…"
    for key in ("anyOf", "oneOf"):
        if key in node:
            parts = [shape(n, depth + 1, indent) for n in node[key]]
            return " | ".join(parts)
    if "allOf" in node:
        return " & ".join(shape(n, depth + 1, indent) for n in node["allOf"])
    if "const" in node:
        return json.dumps(node["const"])
    if "enum" in node:
        return "|".join(json.dumps(v) for v in node["enum"])
    t = node.get("type")
    if t == "object" or "properties" in node:
        props = node.get("properties", {})
        req = set(node.get("required", []))
        if not props:
            extra = node.get("additionalProperties")
            if isinstance(extra, dict):
                return "{[k]: " + shape(extra, depth + 1, indent) + "}"
            if node.get("propertyNames"):
                return "{[k]: any}"
            return "{}"
        pad = indent * (depth + 1)
        lines = []
        for name, sub in props.items():
            opt = "" if name in req else "?"
            lines.append(f"{pad}{name}{opt}: {shape(sub, depth + 1, indent)}")
        return "{\n" + "\n".join(lines) + "\n" + indent * depth + "}"
    if t == "array":
        lim = ""
        if "maxItems" in node:
            lim = f"≤{node['maxItems']}"
        return shape(node.get("items", {}), depth + 1, indent) + f"[]{lim}"
    bits = [str(t)]
    if "format" in node:
        bits.append(node["format"])
    if "minimum" in node or "maximum" in node:
        bits.append(f"[{node.get('minimum', '')}..{node.get('maximum', '')}]")
    if "maxLength" in node:
        bits.append(f"len≤{node['maxLength']}")
    if isinstance(t, list):
        bits[0] = "|".join(t)
    return " ".join(bits)


for path, item in doc["paths"].items():
    for method, op in item.items():
        if method not in ("get", "post", "put", "patch", "delete"):
            continue
        key = f"{method.upper()} {path}"
        if not any(w == key or (w.endswith("*") and key.startswith(w[:-1])) for w in wanted):
            continue
        print("=" * 100)
        print(key, "|", op.get("operationId"), "| gate:", op.get("x-neatlogs-operation-gate"))
        print("security:", [list(s) for s in op.get("security", [])])
        for p in op.get("parameters", []):
            p = resolve(p)
            if p.get("in") == "header" and p.get("name") == "x-project-id":
                continue
            print("  param", p.get("in"), p.get("name"), "required" if p.get("required") else "", shape(p.get("schema", {})))
        body = op.get("requestBody")
        if body:
            body = resolve(body)
            for ct, spec in body.get("content", {}).items():
                print("  body", ct, shape(spec.get("schema", {}), 1))
        for status, resp in op.get("responses", {}).items():
            if not status.startswith("2") and "--errors" not in __import__("os").environ.get("OAS_FLAGS", ""):
                continue
            resp = resolve(resp)
            for ct, spec in (resp.get("content") or {}).items():
                print("  resp", status, ct, shape(spec.get("schema", {}), 1))

